write(B/'source-review.json',{'section':462,'changed_or_new_sources':{p:pin(p)for p in sources},'review':'Existing validated NodeStatisticsSource remains the single map/card/table source; frequency math and source fetching unchanged. StatisticsDialog becomes retained StatisticsPanel in ToolPage. Actual compact-map selection is supplied explicitly; settings reopen preserves the manual query. Stable source/query avoids repeated rebuild, and source reorder preserves selected node type/column/reading. Manual query clears the old mapped caption. Identical updates clear loading status; failures preserve previous data. Unsupported map distances do not clamp. All Compact.present consumers now use ToolPage; obsolete generic owner-dialog route removed, including the remaining hover card consumer. Qt-documented deferred column geometry is followed by one coalesced next-loop row resize. Player-facing map and hover labels simplified; original detailed pool conditions stay expandable. Existing game identity/freshness, note unsaved guard, cache validation and send protection remain.','whole_program_review_complete':False})
write(D/'reuse.json',{'sources':[{'url':'https://github.com/qt/qtbase/blob/v6.11.2/src/widgets/itemviews/qtableview.cpp','blob':'6e4dc5607a92550fe49770c6310e8b09fecd77ed','finding':'QTableView::columnResized starts a zero-duration column resize timer; geometry completes on the next event-loop turn. Use one single-shot QTimer for row reflow, coalescing column resize notifications.'},{'url':'https://doc.qt.io/qtforpython-6/PySide6/QtWidgets/QHeaderView.html','used':'ResizeToContents for short columns; Stretch for effect text.'},{'url':'https://doc.qt.io/qtforpython-6/PySide6/QtWidgets/QAbstractItemView.html','used':'ScrollPerPixel for variable-height wrapped rows.'}],'decision':'Use mature Qt page/table behavior with the established shared public index, instead of adding another browser, fetching service or statistics implementation.','external_foundation':'Existing Qt/qframelesswindow/PyQtDarkTheme runtime; no new dependency.','public_index_sources':{p:pin(p)for p in ['rouge/node_statistics_source.py','rouge/node_statistics_index.py','rouge/public_node_statistics.py']if(R/p).is_file()}})
